const marianaContent:Slide[]=[{"type":"cover","eyebrow":"ENGLISH CLASS","title":"English Class: Playing Games, Places to Visit & Superlatives","text":"Aquí tienes toda la teoría completa y organizada para tu clase de inglés, con vocabulario en inglés y español, reglas gramaticales, ejemplos y ejercicios. El segundo tema contiene únicamente vocabulario, como me pediste."},{"type":"section","eyebrow":"1. Vocabulary: Playing Games 🎮","title":"A. Video games — Videojuegos","items":[{"icon":"•","title":"Video game","detail":"Videojuego"},{"icon":"•","title":"Game controller","detail":"Control de videojuegos"},{"icon":"•","title":"Screen","detail":"Pantalla"},{"icon":"•","title":"Player","detail":"Jugador"},{"icon":"•","title":"Level","detail":"Nivel"},{"icon":"•","title":"Score","detail":"Puntuación"},{"icon":"•","title":"Win","detail":"Ganar"},{"icon":"•","title":"Lose","detail":"Perder"}]},{"type":"section","eyebrow":"1. Vocabulary: Playing Games 🎮","title":"B. Board games — Juegos de mesa","items":[{"icon":"•","title":"Board game","detail":"Juego de mesa"},{"icon":"•","title":"Chess","detail":"Ajedrez"},{"icon":"•","title":"Cards","detail":"Cartas"},{"icon":"•","title":"Dice","detail":"Dados"},{"icon":"•","title":"Puzzle","detail":"Rompecabezas"},{"icon":"•","title":"Rules","detail":"Reglas"},{"icon":"•","title":"Take turns","detail":"Tomar turnos"},{"icon":"•","title":"Piece","detail":"Ficha o pieza"}]},{"type":"section","eyebrow":"1. Vocabulary: Playing Games 🎮","title":"C. Outdoor games — Juegos al aire libre","items":[{"icon":"•","title":"Play soccer","detail":"Jugar fútbol"},{"icon":"•","title":"Play hide-and-seek","detail":"Jugar a las escondidas"},{"icon":"•","title":"Run","detail":"Correr"},{"icon":"•","title":"Jump","detail":"Saltar"},{"icon":"•","title":"Catch","detail":"Atrapar"},{"icon":"•","title":"Team","detail":"Equipo"},{"icon":"•","title":"Ball","detail":"Pelota"},{"icon":"•","title":"Playground","detail":"Zona de juegos"}]},{"type":"lesson","eyebrow":"Grammar: How to talk about playing games","title":"A. Like + verb-ing","text":"Utilizamos esta estructura para expresar gustos y preferencias.","items":[{"icon":"•","title":"Estructura","detail":"Subject + like/likes + verb-ing."},{"icon":"•","title":"I like playing video games.","detail":"Me gusta jugar videojuegos."},{"icon":"•","title":"You like playing chess.","detail":"Te gusta jugar ajedrez."},{"icon":"•","title":"She likes playing soccer.","detail":"A ella le gusta jugar fútbol."},{"icon":"•","title":"He likes playing cards.","detail":"A él le gusta jugar cartas."},{"icon":"•","title":"They like playing board games.","detail":"A ellos les gusta jugar juegos de mesa."}]},{"type":"lesson","eyebrow":"Grammar: How to talk about playing games","title":"Regla importante","text":"Después de like, podemos utilizar un verbo terminado en -ing para expresar una actividad.","items":[{"icon":"•","title":"I, You, We, They","detail":"like"},{"icon":"•","title":"He, She, It","detail":"likes"},{"icon":"•","title":"Play → Playing","detail":""},{"icon":"•","title":"Run → Running","detail":""},{"icon":"•","title":"Swim → Swimming","detail":""},{"icon":"•","title":"Dance → Dancing","detail":""}]},{"type":"lesson","eyebrow":"Grammar: How to talk about playing games","title":"B. Questions about games","items":[{"icon":"•","title":"What games do you like?","detail":"¿Qué juegos te gustan?"},{"icon":"•","title":"Do you like video games?","detail":"¿Te gustan los videojuegos?"},{"icon":"•","title":"What is your favorite game?","detail":"¿Cuál es tu juego favorito?"},{"icon":"•","title":"Who do you play with?","detail":"¿Con quién juegas?"},{"icon":"•","title":"Do you like playing chess?","detail":"¿Te gusta jugar ajedrez?"}]},{"type":"section","eyebrow":"2. Vocabulary: Places to Visit 🗺️","title":"A. Nature and outdoor places — Naturaleza y lugares al aire libre","items":[{"icon":"•","title":"Beach","detail":"Playa"},{"icon":"•","title":"Mountain","detail":"Montaña"},{"icon":"•","title":"Forest","detail":"Bosque"},{"icon":"•","title":"Park","detail":"Parque"},{"icon":"•","title":"Lake","detail":"Lago"},{"icon":"•","title":"River","detail":"Río"},{"icon":"•","title":"Waterfall","detail":"Cascada"},{"icon":"•","title":"Island","detail":"Isla"},{"icon":"•","title":"Cave","detail":"Cueva"},{"icon":"•","title":"Desert","detail":"Desierto"}]},{"type":"section","eyebrow":"2. Vocabulary: Places to Visit 🗺️","title":"B. Cultural places — Lugares culturales","items":[{"icon":"•","title":"Museum","detail":"Museo"},{"icon":"•","title":"Art gallery","detail":"Galería de arte"},{"icon":"•","title":"Library","detail":"Biblioteca"},{"icon":"•","title":"Historical monument","detail":"Monumento histórico"},{"icon":"•","title":"Castle","detail":"Castillo"},{"icon":"•","title":"Church","detail":"Iglesia"},{"icon":"•","title":"Cathedral","detail":"Catedral"},{"icon":"•","title":"Theater","detail":"Teatro"}]},{"type":"section","eyebrow":"2. Vocabulary: Places to Visit 🗺️","title":"C. Entertainment places — Lugares de entretenimiento","items":[{"icon":"•","title":"Amusement park","detail":"Parque de diversiones"},{"icon":"•","title":"Zoo","detail":"Zoológico"},{"icon":"•","title":"Cinema","detail":"Cine"},{"icon":"•","title":"Shopping mall","detail":"Centro comercial"},{"icon":"•","title":"Restaurant","detail":"Restaurante"},{"icon":"•","title":"Aquarium","detail":"Acuario"},{"icon":"•","title":"Stadium","detail":"Estadio"},{"icon":"•","title":"Water park","detail":"Parque acuático"}]},{"type":"section","eyebrow":"2. Vocabulary: Places to Visit 🗺️","title":"D. Tourist attractions — Atracciones turísticas","items":[{"icon":"•","title":"Tower","detail":"Torre"},{"icon":"•","title":"Bridge","detail":"Puente"},{"icon":"•","title":"Palace","detail":"Palacio"},{"icon":"•","title":"Square","detail":"Plaza"},{"icon":"•","title":"Ancient ruins","detail":"Ruinas antiguas"},{"icon":"•","title":"Botanical garden","detail":"Jardín botánico"},{"icon":"•","title":"National park","detail":"Parque nacional"},{"icon":"•","title":"Monument","detail":"Monumento"}]},{"type":"section","eyebrow":"3. Grammar: Superlatives","title":"Superlatives","text":"Los superlativos se utilizan para expresar que una persona, animal, objeto o lugar tiene una característica en el grado más alto dentro de un grupo.","items":[{"icon":"•","title":"En español usamos expresiones como:","detail":""},{"icon":"•","title":"El más alto.","detail":""},{"icon":"•","title":"La más bonita.","detail":""},{"icon":"•","title":"El más rápido.","detail":""},{"icon":"•","title":"El mejor.","detail":""},{"icon":"•","title":"El lugar más interesante.","detail":""},{"icon":"•","title":"In English","detail":"the + superlative adjective"},{"icon":"•","title":"The tallest building","detail":"El edificio más alto."},{"icon":"•","title":"The most beautiful beach","detail":"La playa más bonita."},{"icon":"•","title":"The fastest animal","detail":"El animal más rápido."}]},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"A. Short adjectives — Adjetivos cortos","text":"Con muchos adjetivos cortos agregamos -est al final.","items":[{"icon":"•","title":"Tall — Alto — The tallest","detail":"El más alto"},{"icon":"•","title":"Small — Pequeño — The smallest","detail":"El más pequeño"},{"icon":"•","title":"Fast — Rápido — The fastest","detail":"El más rápido"},{"icon":"•","title":"Short — Corto / bajo — The shortest","detail":"El más corto / bajo"},{"icon":"•","title":"Long — Largo — The longest","detail":"El más largo"},{"icon":"•","title":"Old — Viejo / antiguo — The oldest","detail":"El más viejo / antiguo"},{"icon":"•","title":"Young — Joven — The youngest","detail":"El más joven"}]},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"Examples","items":[{"icon":"•","title":"The giraffe is the tallest animal in the zoo.","detail":"La jirafa es el animal más alto del zoológico."},{"icon":"•","title":"This is the smallest room in the house.","detail":"Esta es la habitación más pequeña de la casa."},{"icon":"•","title":"The cheetah is the fastest land animal.","detail":"El guepardo es el animal terrestre más rápido."}]},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"B. Adjectives ending in -e","text":"Si el adjetivo termina en -e, agregamos solamente -st.","items":[{"icon":"•","title":"Large — Grande — The largest","detail":""},{"icon":"•","title":"Nice — Agradable — The nicest","detail":""},{"icon":"•","title":"Cute — Bonito / tierno — The cutest","detail":""}],"note":"Example: This is the largest park in the city. — Este es el parque más grande de la ciudad."},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"C. Adjectives ending in consonant + y","text":"Cuando el adjetivo termina en consonante + y, cambiamos la y por i y agregamos -est.","items":[{"icon":"•","title":"Happy — Feliz — The happiest","detail":""},{"icon":"•","title":"Easy — Fácil — The easiest","detail":""},{"icon":"•","title":"Busy — Ocupado / concurrido — The busiest","detail":""},{"icon":"•","title":"Pretty — Bonito — The prettiest","detail":""}],"note":"Examples: Today is the happiest day of my life. — Hoy es el día más feliz de mi vida. · This is the busiest park in the city. — Este es el parque más concurrido de la ciudad."},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"D. Double the final consonant — Duplicar la consonante final","text":"En algunos adjetivos cortos que terminan en consonante-vocal-consonante, duplicamos la consonante final antes de agregar -est.","items":[{"icon":"•","title":"Big — Grande — The biggest","detail":""},{"icon":"•","title":"Hot — Caliente — The hottest","detail":""},{"icon":"•","title":"Thin — Delgado / fino — The thinnest","detail":""}],"note":"Examples: This is the biggest amusement park in the region. — Este es el parque de diversiones más grande de la región. · July is the hottest month here. — Julio es el mes más caluroso aquí."},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"E. Long adjectives — Adjetivos largos","text":"Con muchos adjetivos de dos o más sílabas utilizamos: the most + adjective","items":[{"icon":"•","title":"Beautiful — Hermoso — The most beautiful","detail":"El más hermoso"},{"icon":"•","title":"Interesting — Interesante — The most interesting","detail":"El más interesante"},{"icon":"•","title":"Expensive — Costoso — The most expensive","detail":"El más costoso"},{"icon":"•","title":"Popular — Popular — The most popular","detail":"El más popular"},{"icon":"•","title":"Comfortable — Cómodo — The most comfortable","detail":"El más cómodo"},{"icon":"•","title":"Exciting — Emocionante — The most exciting","detail":"El más emocionante"}]},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"Examples","items":[{"icon":"•","title":"This is the most beautiful beach in the country.","detail":"Esta es la playa más hermosa del país."},{"icon":"•","title":"The museum is the most interesting place in the city.","detail":"El museo es el lugar más interesante de la ciudad."},{"icon":"•","title":"This is the most expensive restaurant in town.","detail":"Este es el restaurante más costoso de la ciudad."}]},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"F. Irregular superlatives — Superlativos irregulares","text":"Algunos adjetivos no siguen las reglas anteriores y debemos aprender sus formas de memoria.","items":[{"icon":"•","title":"Good — Bueno — The best","detail":"El mejor"},{"icon":"•","title":"Bad — Malo — The worst","detail":"El peor"},{"icon":"•","title":"Far — Lejos — The farthest / furthest","detail":"El más lejano"}],"note":"Examples: This is the best restaurant in the city. — Este es el mejor restaurante en la ciudad. · That is the worst game ever. — Ese es el peor juego de todos. · This is the farthest place from my house. — Este es el lugar más lejano de mi casa."},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"G. Sentence structure — Estructura de las oraciones","text":"La estructura más común para utilizar superlativos es:","items":[{"icon":"•","title":"Subject + verb + the + superlative + complement","detail":""},{"icon":"•","title":"Example: The beach is the most beautiful place in the city.","detail":"La playa es el lugar más hermoso de la ciudad."},{"icon":"•","title":"The lion is the strongest animal in the zoo.","detail":"El león es el animal más fuerte del zoológico."},{"icon":"•","title":"Mount Everest is the highest mountain in the world.","detail":"El monte Everest es la montaña más alta del mundo."},{"icon":"•","title":"Chess is the most difficult game for me.","detail":"El ajedrez es el juego más difícil para mí."},{"icon":"•","title":"The roller coaster is the most exciting attraction in the park.","detail":"La montaña rusa es la atracción más emocionante del parque."}]},{"type":"lesson","eyebrow":"3. Grammar: Superlatives","title":"Important","text":"Important: Normalmente utilizamos the antes del superlativo: the biggest, the best, the most beautiful."},{"type":"quiz","eyebrow":"4. Practice: Exercises","title":"Mini quiz","text":"0 de 8"}];marianaSlides.splice(0,marianaSlides.length,...marianaContent);quiz.splice(0,quiz.length,...[{"question":"1. I like ______ video games.","options":["play","playing","plays"],"answer":1,"why":"Respuesta correcta: playing."},{"question":"2. A place where you can see paintings is a ______.","options":["museum","river","mountain"],"answer":0,"why":"Respuesta correcta: museum."},{"question":"3. The superlative of tall is ______.","options":["the most tall","the tallest","the taller"],"answer":1,"why":"Respuesta correcta: the tallest."},{"question":"4. The superlative of beautiful is ______.","options":["the beautifulest","the beautifullest","the most beautiful"],"answer":2,"why":"Respuesta correcta: the most beautiful."},{"question":"5. The superlative of good is ______.","options":["the goodest","the best","the better"],"answer":1,"why":"Respuesta correcta: the best."},{"question":"6. I would like ______ the zoo.","options":["visit","visiting","to visit"],"answer":2,"why":"Respuesta correcta: to visit."},{"question":"7. The superlative of big is ______.","options":["the bigest","the biggest","the most big"],"answer":1,"why":"Respuesta correcta: the biggest."},{"question":"8. A place where you can see many animals is a ______.","options":["zoo","library","cinema"],"answer":0,"why":"Respuesta correcta: zoo."}]);
salomeSlides.splice(0,salomeSlides.length,...([{"type":"cover","eyebrow":"GRADE 6 · TEORÍA Y PRÁCTICA DE COMPRENSIÓN LECTORA","title":"English Reading – A1","text":"La clase estará enfocada en comprender textos cortos en inglés, identificar información específica, reconocer ideas principales y responder preguntas. Tomaremos como referencia el nivel A1 y el estilo de las lecturas que compartiste del Colegio Santo Ángel de la Guarda. En lugar de empezar con explicaciones gramaticales extensas, trabajaremos directamente con lecturas, preguntas de comprensión y ejercicios similares a los de una evaluación escolar."},{"type":"strategy","eyebrow":"RECOMENDACIONES PARA RESOLVER UNA LECTURA","title":"Read, underline, answer","items":[{"icon":"•","title":"1. Read the title","detail":"lee el título para identificar el tema."},{"icon":"•","title":"2. Read the text","detail":"haz una primera lectura para comprender la idea general."},{"icon":"•","title":"3. Underline keywords","detail":"identifica nombres, lugares, fechas, cantidades y palabras importantes."},{"icon":"•","title":"4. Read the questions","detail":"revisa qué información debes encontrar."},{"icon":"•","title":"5. Find the answer in the text","detail":"busca la evidencia en la lectura antes de responder."},{"icon":"•","title":"6. Check your answers","detail":"verifica que tu respuesta coincida con la información del texto."}]},{"type":"lesson","eyebrow":"VOCABULARIO ÚTIL PARA LAS PREGUNTAS","title":"Question words","items":[{"icon":"•","title":"Who?","detail":"¿Quién?"},{"icon":"•","title":"What?","detail":"¿Qué? / ¿Cuál?"},{"icon":"•","title":"Where?","detail":"¿Dónde?"},{"icon":"•","title":"When?","detail":"¿Cuándo?"},{"icon":"•","title":"Why?","detail":"¿Por qué?"},{"icon":"•","title":"How?","detail":"¿Cómo?"},{"icon":"•","title":"How many?","detail":"¿Cuántos?"},{"icon":"•","title":"Which?","detail":"¿Cuál? / ¿Qué opción?"}]},{"type":"strategy","eyebrow":"QUESTION TYPES","title":"True or False · Multiple choice","items":[{"icon":"•","title":"True or False","detail":"indica si una afirmación es verdadera o falsa según la lectura. Cuando la instrucción dice Why?, debes justificar la respuesta con información del texto."},{"icon":"•","title":"Multiple choice","detail":"selecciona la opción correcta entre A, B, C o D. No elijas una opción solamente porque contiene palabras que aparecen en la lectura; comprueba que responda la pregunta."}]},{"type":"reading","eyebrow":"READING 1 · A SPECIAL SCHOOL DAY","title":"Reading 1. A special school day","time":"15 min","text":"Read the text and answer the questions.","paragraphs":["My School Festival. Hello! My name is Daniel, and I am twelve years old. I study at Green Valley School. Every year, my school has a festival in October. Students prepare games, music and traditional food.","This year, my class has a small restaurant. We sell sandwiches, juice and cakes. My best friend, Lucas, plays the guitar with other students. My sister helps the teachers decorate the classrooms with balloons and flowers.","The festival starts at nine o’clock in the morning and finishes at three o’clock in the afternoon. My parents come to the school at eleven o’clock. We have a great time together!"],"questions":[{"prompt":"1. How old is Daniel?","options":[],"answer":"twelve years old","paragraph":0,"hint":"Find Daniel’s age in the first two sentences.","why":"He is twelve years old.","format":"short","accepted":["He is twelve years old.","He is twelve.","Twelve years old."]},{"prompt":"2. When does the school festival take place?","options":[],"answer":"In October","paragraph":0,"hint":"Look for the month in the first paragraph.","why":"The festival takes place in October.","format":"short","accepted":["In October.","October."]},{"prompt":"3. What does Daniel’s class sell?","options":[],"answer":"Sandwiches, juice and cakes","paragraph":1,"hint":"Find the sentence that begins “We sell…”.","why":"They sell sandwiches, juice and cakes.","format":"short","accepted":["Sandwiches, juice and cakes.","They sell sandwiches, juice and cakes."]},{"prompt":"4. What instrument does Lucas play?","options":[],"answer":"The guitar","paragraph":1,"hint":"Look for Lucas’s action in paragraph 2.","why":"Lucas plays the guitar.","format":"short","accepted":["The guitar.","He plays the guitar."]},{"prompt":"5. What time does the festival finish?","options":[],"answer":"At three o’clock in the afternoon","paragraph":2,"hint":"Find the festival schedule in the last paragraph.","why":"It finishes at three o’clock in the afternoon.","format":"short","accepted":["At three o’clock in the afternoon.","At 3 o’clock in the afternoon."]}]},{"type":"reading","eyebrow":"READING 2 · PANCAKE DAY","title":"Reading 2. Pancake Day","time":"17 min","text":"Read the text. Write True or False and explain your answers.","paragraphs":["A Delicious Tradition. Pancake Day is a popular tradition in the United Kingdom. It usually takes place in February or March. On this day, many families make pancakes at home. They often eat them with lemon, sugar, fruit or chocolate.","Some towns organize special pancake races. People run while carrying a frying pan with a pancake inside. During the race, they toss the pancake into the air and catch it again. If the pancake falls on the ground, they may lose the race!","Children and adults enjoy this tradition. Today, many people celebrate Pancake Day because it is fun and they love eating pancakes."],"questions":[{"prompt":"1. Pancake Day is a tradition in the United Kingdom. True / False","options":["True","False"],"answer":0,"paragraph":0,"hint":"Check the first sentence.","why":"True. Pancake Day is a popular tradition in the United Kingdom.","format":"tf"},{"prompt":"2. People usually celebrate Pancake Day in July. True / False","options":["True","False"],"answer":1,"paragraph":0,"hint":"Find the months named in the second sentence.","why":"False. It usually takes place in February or March.","format":"tf"},{"prompt":"3. People can eat pancakes with fruit or chocolate. True / False","options":["True","False"],"answer":0,"paragraph":0,"hint":"Check the list of pancake toppings.","why":"True. Fruit and chocolate are listed.","format":"tf"},{"prompt":"4. During pancake races, people carry a frying pan. True / False","options":["True","False"],"answer":0,"paragraph":1,"hint":"Find what people carry while they run.","why":"True. They run while carrying a frying pan with a pancake inside.","format":"tf"},{"prompt":"5. Only children celebrate Pancake Day. True / False","options":["True","False"],"answer":1,"paragraph":2,"hint":"The first sentence of paragraph 3 names who enjoys it.","why":"False. Children and adults enjoy this tradition.","format":"tf"}]},{"type":"reading","eyebrow":"READING 2 · PANCAKE DAY","title":"Correct the false statements","text":"For questions 1–5, correct the false statements using information from the text.","time":"8 min","drills":[{"prompt":"2. People usually celebrate Pancake Day in July.","answer":"It usually takes place in February or March."},{"prompt":"5. Only children celebrate Pancake Day.","answer":"Children and adults enjoy this tradition."}]},{"type":"reading","eyebrow":"READING 3 · A WEEKEND IN LONDON","title":"Reading 3. A weekend in London","time":"18 min","text":"Read the text and choose the correct answer: A, B, C or D.","paragraphs":["Dear Sophie, I am having a wonderful weekend in London with my family. We arrived on Friday afternoon and are staying at a hotel near the city centre.","Yesterday, we visited the Natural History Museum. I saw dinosaur skeletons and learned about different animals. My little brother loved the museum shop because it had many toys and books.","Today, we are going to visit the London Eye. My mother wants to take lots of photographs, and my father wants to try some traditional British food. In the evening, we are going to eat at a small restaurant near our hotel.","Tomorrow, we are travelling home by train. I really like London because there are many interesting places to visit! Love, Emma"],"questions":[{"prompt":"1. Where is Emma staying?","options":["A. At her grandmother’s house.","B. At a hotel near the city centre.","C. At a museum.","D. At a friend’s house."],"answer":1,"paragraph":0,"hint":"Find the sentence that says where the family is staying.","why":"B. At a hotel near the city centre.","format":"multiple"},{"prompt":"2. What did Emma visit yesterday?","options":["A. The London Eye.","B. A shopping mall.","C. The Natural History Museum.","D. A train station."],"answer":2,"paragraph":1,"hint":"Look for the first sentence of paragraph 2.","why":"C. The Natural History Museum.","format":"multiple"},{"prompt":"3. What did Emma’s little brother like?","options":["A. The museum shop.","B. The restaurant.","C. The hotel room.","D. The train."],"answer":0,"paragraph":1,"hint":"Find what the brother loved in paragraph 2.","why":"A. The museum shop.","format":"multiple"},{"prompt":"4. What does Emma’s mother want to do?","options":["A. Buy some toys.","B. Take photographs.","C. Travel by bus.","D. Visit her friends."],"answer":1,"paragraph":2,"hint":"Look for the sentence about Emma’s mother.","why":"B. Take photographs.","format":"multiple"},{"prompt":"5. How are they travelling home?","options":["A. By plane.","B. By car.","C. By bus.","D. By train."],"answer":3,"paragraph":3,"hint":"Find the first sentence of the last paragraph.","why":"D. By train.","format":"multiple"}]},{"type":"reading","eyebrow":"READING 4 · TIPS FOR A HEALTHY LIFESTYLE","title":"Reading 4. Tips for a healthy lifestyle","time":"18 min","text":"Read each paragraph and match it with the best title.","paragraphs":["Paragraph 1. Eat fruit and vegetables every day. They provide important vitamins and help your body stay healthy. Try to eat different kinds of food and have a balanced breakfast before school.","Paragraph 2. Your body needs water every day. Take a bottle of water to school and drink regularly, especially when the weather is hot or you play sports.","Paragraph 3. Walking, dancing, swimming and playing football are good activities. Choose something you enjoy and make time for movement every day.","Paragraph 4. Children and teenagers need enough rest to feel good and concentrate at school. Try to go to bed at a regular time and avoid using your phone when it is time to sleep.","Paragraph 5. Talking, playing and laughing with other people can make your day more enjoyable. Spend time with your family and friends, and remember to be kind to others."],"questions":[{"prompt":"Paragraph 1. Title: __________________________","options":["A. Drink enough water","B. Get enough sleep","C. Eat healthy food","D. Be physically active","E. Spend time with friends"],"answer":2,"paragraph":0,"hint":"Look for the paragraph’s food and breakfast recommendations.","why":"C. Eat healthy food.","format":"match"},{"prompt":"Paragraph 2. Title: __________________________","options":["A. Drink enough water","B. Get enough sleep","C. Eat healthy food","D. Be physically active","E. Spend time with friends"],"answer":0,"paragraph":1,"hint":"The paragraph mentions a bottle and drinking regularly.","why":"A. Drink enough water.","format":"match"},{"prompt":"Paragraph 3. Title: __________________________","options":["A. Drink enough water","B. Get enough sleep","C. Eat healthy food","D. Be physically active","E. Spend time with friends"],"answer":3,"paragraph":2,"hint":"Find the activities and movement recommendation.","why":"D. Be physically active.","format":"match"},{"prompt":"Paragraph 4. Title: __________________________","options":["A. Drink enough water","B. Get enough sleep","C. Eat healthy food","D. Be physically active","E. Spend time with friends"],"answer":1,"paragraph":3,"hint":"The paragraph is about rest and bedtime.","why":"B. Get enough sleep.","format":"match"},{"prompt":"Paragraph 5. Title: __________________________","options":["A. Drink enough water","B. Get enough sleep","C. Eat healthy food","D. Be physically active","E. Spend time with friends"],"answer":4,"paragraph":4,"hint":"Find the paragraph’s advice about family, friends and other people.","why":"E. Spend time with friends.","format":"match"}]},{"type":"reading","eyebrow":"READING 5 · WHERE ARE YOU GOING TO SHOP?","title":"Reading 5. Where are you going to shop?","time":"18 min","text":"Read the message and choose the correct answer.","paragraphs":["Hi Alex, Welcome to our town! There are many good shops here, and I can show you around this weekend.","On Saturday morning, I am going to the clothes shop next to the supermarket. It sells T-shirts, trousers and shoes. After that, I need to buy some apples, milk and bread at the supermarket.","In the afternoon, my brother and I are going to the sports shop because he needs a new football. The sports shop is opposite the cinema. We sometimes watch a film there after shopping.","On Sunday, my family is going to the shopping mall. There is a big bookshop on the second floor, and I want to buy a book for school. Would you like to come with us? See you soon! Mia"],"questions":[{"prompt":"1. Where is the clothes shop?","options":["A. Next to the supermarket.","B. Opposite the cinema.","C. On the second floor.","D. Near the school."],"answer":0,"paragraph":1,"hint":"Find the location in the first sentence of paragraph 2.","why":"A. Next to the supermarket.","format":"multiple"},{"prompt":"2. What does Mia need to buy at the supermarket?","options":["A. A football and a book.","B. T-shirts and trousers.","C. Apples, milk and bread.","D. Shoes and a film."],"answer":2,"paragraph":1,"hint":"Look for the list of food in paragraph 2.","why":"C. Apples, milk and bread.","format":"multiple"},{"prompt":"3. Why is Mia’s brother going to the sports shop?","options":["A. He wants to buy a book.","B. He needs a new football.","C. He wants to buy some food.","D. He needs new shoes for school."],"answer":1,"paragraph":2,"hint":"The reason is given in the first sentence of paragraph 3.","why":"B. He needs a new football.","format":"multiple"},{"prompt":"4. Where is the bookshop?","options":["A. Next to the supermarket.","B. Opposite the cinema.","C. On the second floor of the shopping mall.","D. Inside the sports shop."],"answer":2,"paragraph":3,"hint":"Find the sentence about the bookshop on Sunday.","why":"C. On the second floor of the shopping mall.","format":"multiple"},{"prompt":"5. What can we infer about Mia?","options":["A. She wants to go shopping with Alex.","B. She never visits the cinema.","C. She works at the supermarket.","D. She does not like reading."],"answer":0,"paragraph":3,"hint":"Look at Mia’s invitation at the end of the message.","why":"A. She wants to go shopping with Alex.","format":"multiple"}]},{"type":"reading","eyebrow":"READING 6 · EMPTY HOUSES IN A SMALL TOWN","title":"Reading 6. Empty houses in a small town","time":"15 min","text":"Read the news and answer the questions.","paragraphs":["Homes for Everyone. In a small town, many houses are empty. Some houses are very old and need repairs. Other houses are too expensive for young families.","The town government wants to help. It plans to repair some old houses and make them safe for people. Workers are checking the roofs, windows and doors. They are also looking at the water and electricity systems.","Many families hope to find a home soon. The town wants everyone to have a safe place to live."],"questions":[{"prompt":"1. Why are some houses empty?","options":[],"answer":"Some are old and need repairs; others are too expensive","paragraph":0,"hint":"Find the two reasons in paragraph 1.","why":"Some houses are old and need repairs; others are too expensive for young families.","format":"short","accepted":["Some are old and need repairs; others are too expensive.","Some houses are old and need repairs; other houses are too expensive for young families."]},{"prompt":"2. What does the town government want to do?","options":[],"answer":"Repair old houses and make them safe","paragraph":1,"hint":"Look for the government’s plan in paragraph 2.","why":"It plans to repair some old houses and make them safe for people.","format":"short","accepted":["Repair old houses and make them safe.","To repair some old houses and make them safe for people."]},{"prompt":"3. What are workers checking?","options":[],"answer":"Roofs, windows, doors, water and electricity systems","paragraph":1,"hint":"Find what workers are checking in paragraph 2.","why":"They are checking the roofs, windows, doors, and the water and electricity systems.","format":"short","accepted":["Roofs, windows, doors, water and electricity systems.","The roofs, windows, doors, and water and electricity systems."]},{"prompt":"4. Who hopes to find a home soon?","options":[],"answer":"Many families","paragraph":2,"hint":"Read the first sentence of paragraph 3.","why":"Many families hope to find a home soon.","format":"short","accepted":["Many families."]},{"prompt":"5. Choose the best title:","options":["A. A New Shopping Centre","B. Homes for Everyone","C. A School in the Town","D. A Holiday by the Sea"],"answer":1,"paragraph":0,"hint":"Choose the title that covers the housing problem and the town’s plan.","why":"B. Homes for Everyone.","format":"multiple"}]},{"type":"reading","eyebrow":"READING 7 · A PHONE APP FOR EVERYDAY LIFE","title":"Reading 7. A phone app for everyday life","time":"17 min","text":"Read the text and answer the questions.","paragraphs":["A Helpful App. Sofia is thirteen years old and uses her phone to organize her daily activities. Every morning, she checks the weather and looks at her school timetable. Her favourite app also helps her make a list of homework and important dates.","Sofia does not use her phone all day. During lunch, she talks to her friends. In the afternoon, she does her homework and sometimes plays games with her younger brother.","At night, Sofia prepares her schoolbag for the next day. She turns off her phone before going to bed because she wants to sleep well. She thinks technology is useful when people use it carefully."],"questions":[{"prompt":"1. What does Sofia check every morning?","options":["A. The news and television.","B. The weather and her school timetable.","C. Her shopping list.","D. Her friends’ homework."],"answer":1,"paragraph":0,"hint":"Find the two things Sofia checks every morning.","why":"B. The weather and her school timetable.","format":"multiple"},{"prompt":"2. What does her favourite app help her organize?","options":["A. Homework and important dates.","B. Her meals at a restaurant.","C. Her family’s holidays.","D. Her sports equipment."],"answer":0,"paragraph":0,"hint":"Look for what the app helps her list.","why":"A. Homework and important dates.","format":"multiple"},{"prompt":"3. What does Sofia do during lunch?","options":["A. Plays games on her phone.","B. Goes to sleep.","C. Talks to her friends.","D. Does all her homework."],"answer":2,"paragraph":1,"hint":"Find the sentence that begins “During lunch”.","why":"C. Talks to her friends.","format":"multiple"},{"prompt":"4. Why does Sofia turn off her phone at night?","options":["A. Because her phone is broken.","B. Because she wants to sleep well.","C. Because she does not like technology.","D. Because she has no homework."],"answer":1,"paragraph":2,"hint":"Find her reason in the first two sentences of paragraph 3.","why":"B. Because she wants to sleep well.","format":"multiple"},{"prompt":"5. What is the main idea of the text?","options":["A. Phones are only for playing games.","B. Sofia does not like school.","C. Technology can be useful when used carefully.","D. Students should never use apps."],"answer":2,"paragraph":2,"hint":"Consider both how Sofia uses her phone and the final sentence.","why":"C. Technology can be useful when used carefully.","format":"multiple"}]},{"type":"reading","eyebrow":"READING 8 · SCHOOL","title":"My First Day at a New School","time":"5 questions","paragraphs":["My name is Lucas, and I am twelve years old. Last Monday, I started at a new school. I was nervous because I did not know anyone. My classroom is on the second floor, next to the library.","My English teacher is very friendly. She speaks slowly and helps students when they have problems. At lunchtime, I sat with two boys called Daniel and Peter. They like football and video games, just like me.","After school, I walked home with Daniel. We live on the same street, and our houses are near a small park. I think I am going to enjoy my new school!"],"questions":[{"prompt":"How old is Lucas?","options":["Ten years old.","Eleven years old.","Twelve years old.","Thirteen years old."],"answer":2,"paragraph":0,"hint":"Busca la edad en la primera oración.","why":"Lucas is twelve years old.","format":"multiple"},{"prompt":"Where is Lucas's classroom?","options":["Next to the library on the second floor.","Next to the school restaurant.","On the first floor, near the office.","Behind the school playground."],"answer":0,"paragraph":0,"hint":"Ubica “classroom” y localiza el piso y el lugar cercano.","why":"It is on the second floor, next to the library.","format":"multiple"},{"prompt":"Why was Lucas nervous on his first day?","options":["He did not like his teacher.","He did not know anyone.","He forgot his schoolbag.","He was late for class."],"answer":1,"paragraph":0,"hint":"La razón aparece después de “because”.","why":"He did not know anyone.","format":"multiple"},{"prompt":"What do Daniel and Peter like?","options":["Swimming and dancing.","Reading and cooking.","Basketball and music.","Football and video games."],"answer":3,"paragraph":1,"hint":"Busca los nombres Daniel and Peter.","why":"They like football and video games.","format":"multiple"},{"prompt":"How did Lucas get home after school?","options":["By bus.","By bicycle.","On foot with Daniel.","By car with his parents."],"answer":2,"paragraph":2,"hint":"La primera oración del último párrafo indica cómo fue a casa.","why":"He walked home with Daniel.","format":"multiple"}]},{"type":"reading","eyebrow":"READING 9 · NATURE","title":"A Day at the National Park","time":"5 questions","paragraphs":["Last Saturday, Emma and her family visited a national park near their city. They left home at seven o’clock in the morning because they wanted to arrive early.","First, they walked along a path through the forest. They saw colourful birds, butterflies and a small waterfall. Emma’s younger brother took many photographs with his camera.","At noon, the family stopped near a lake to eat sandwiches, fruit and drink water. They did not leave any rubbish because they wanted to keep the park clean.","In the afternoon, they visited a small information centre. A park worker talked about the animals and explained why it is important to protect nature. Emma learned a lot and wants to visit the park again."],"questions":[{"prompt":"When did Emma and her family visit the park?","options":["Last Friday.","Last Saturday.","Last Sunday.","On Monday morning."],"answer":1,"paragraph":0,"hint":"Busca el día en la primera oración.","why":"Last Saturday.","format":"multiple"},{"prompt":"Why did the family leave home at seven o'clock?","options":["They wanted to arrive early.","They wanted to buy a camera.","They needed to meet a teacher.","They wanted to have lunch at home."],"answer":0,"paragraph":0,"hint":"Localiza la explicación que sigue a “because”.","why":"They wanted to arrive early.","format":"multiple"},{"prompt":"What did Emma's younger brother do?","options":["He fed the birds.","He swam in the lake.","He took photographs.","He cleaned the information centre."],"answer":2,"paragraph":1,"hint":"Busca “younger brother” en el segundo párrafo.","why":"He took photographs.","format":"multiple"},{"prompt":"What did the family eat near the lake?","options":["Pizza and ice cream.","Hamburgers and chips.","Rice and chicken.","Sandwiches and fruit."],"answer":3,"paragraph":2,"hint":"Revisa la lista de comida en el párrafo del mediodía.","why":"Sandwiches and fruit.","format":"multiple"},{"prompt":"What did Emma learn at the information centre?","options":["How to take better photographs.","Why it is important to protect nature.","How to swim in the lake.","How to find a restaurant in the city."],"answer":1,"paragraph":3,"hint":"Busca lo que explicó el trabajador del parque.","why":"Why it is important to protect nature.","format":"multiple"}]},{"type":"reading","eyebrow":"READING 10 · SCHOOL","title":"The School Sports Competition","time":"6 questions","paragraphs":["Every year, Hill School organizes a sports competition in May. Students from different classes take part in football, basketball, running and swimming.","This year, the competition takes place on Friday. The activities start at eight thirty in the morning. Students must wear comfortable sports clothes and bring a bottle of water.","Anna is in the basketball team. She practises with her friends every Tuesday and Thursday after school. Her brother, Tom, prefers running because he enjoys individual sports.","The teachers organize the event, and parents can come to watch. At the end of the day, the school gives medals to the winners. Anna hopes her team wins, but she says that having fun is more important than winning."],"questions":[{"prompt":"In which month does Hill School organize the competition?","options":["March.","April.","May.","June."],"answer":2,"paragraph":0,"hint":"Busca el mes en la primera oración.","why":"May.","format":"multiple"},{"prompt":"What time do the activities start?","options":["At seven thirty.","At eight thirty.","At nine thirty.","At ten thirty."],"answer":1,"paragraph":1,"hint":"Busca la hora en el segundo párrafo.","why":"At eight thirty.","format":"multiple"},{"prompt":"How often does Anna practise basketball?","options":["Every day.","Only on Fridays.","Once a month.","On Tuesdays and Thursdays."],"answer":3,"paragraph":2,"hint":"Fíjate en los días de práctica de Anna.","why":"On Tuesdays and Thursdays.","format":"multiple"},{"prompt":"Why does Tom prefer running?","options":["He enjoys individual sports.","He does not like school.","He wants to become a teacher.","His sister asks him to run."],"answer":0,"paragraph":2,"hint":"La respuesta viene después de “because”.","why":"He enjoys individual sports.","format":"multiple"},{"prompt":"What does the school give to the winners?","options":["Books.","School bags.","Medals.","Footballs."],"answer":2,"paragraph":3,"hint":"Busca “winners” en el último párrafo.","why":"Medals.","format":"multiple"},{"prompt":"What is Anna's opinion about the competition?","options":["Winning is the only important thing.","Having fun is more important than winning.","Students should not play sports.","Parents should organize the activities."],"answer":1,"paragraph":3,"hint":"Busca la opinión de Anna en la última oración.","why":"Having fun is more important than winning.","format":"multiple"}]},{"type":"reading","eyebrow":"READING 11 · TOWN","title":"A New Café in Town","time":"6 questions","paragraphs":["A new café called Sunny Café opened in the town centre two weeks ago. It is next to the public library and opposite a large shopping centre.","The café opens from Monday to Saturday, from eight o’clock in the morning until six o’clock in the evening. It sells sandwiches, salads, cakes and different drinks. The chocolate cake is very popular with young customers.","On Wednesdays, students get a special discount if they show their school ID. There is also a small garden behind the café, where people can sit and read books.","Sofia visited the café with her mother last Saturday. She ordered a cheese sandwich and orange juice, while her mother had a salad and coffee. Sofia liked the café because it was quiet, clean and comfortable. She wants to return with her friends next week."],"questions":[{"prompt":"Where is Sunny Café?","options":["Inside the public library.","Next to the public library.","Behind the school.","Opposite the hospital."],"answer":1,"paragraph":0,"hint":"Busca el café en la primera parte del texto.","why":"Next to the public library.","format":"multiple"},{"prompt":"On which day is the café closed?","options":["Monday.","Wednesday.","Friday.","Sunday."],"answer":3,"paragraph":1,"hint":"El café abre de Monday a Saturday. ¿Qué día queda fuera?","why":"Sunday.","format":"multiple"},{"prompt":"What do students need to get a discount?","options":["Their school ID.","A library card.","A shopping receipt.","A birthday invitation."],"answer":0,"paragraph":2,"hint":"Busca “discount” en el tercer párrafo.","why":"Their school ID.","format":"multiple"},{"prompt":"What can people do in the garden behind the café?","options":["Play football.","Buy school uniforms.","Sit and read books.","Watch films."],"answer":2,"paragraph":2,"hint":"Revisa la descripción del jardín.","why":"Sit and read books.","format":"multiple"},{"prompt":"What did Sofia order?","options":["A salad and coffee.","A chocolate cake and tea.","A cheese sandwich and orange juice.","A hamburger and water."],"answer":2,"paragraph":3,"hint":"Busca “Sofia visited” y sus alimentos.","why":"A cheese sandwich and orange juice.","format":"multiple"},{"prompt":"Why did Sofia like the café?","options":["It was very noisy.","It was quiet, clean and comfortable.","It was inside her school.","It was open every day of the year."],"answer":1,"paragraph":3,"hint":"Busca la razón después de “because”.","why":"It was quiet, clean and comfortable.","format":"multiple"}]},{"type":"reading","eyebrow":"USE OF ENGLISH · A1","title":"Exercise A. The moon","time":"5 questions","paragraphs":["The moon is beautiful at night. Sometimes it looks big and round, but on other nights it looks smaller. Many children want to travel to the moon, but they (1) ______ do it easily.","The moon is not (2) ______ good place for a holiday. It can be very cold (3) ______ very hot. There is no grass, and there isn’t (4) ______ food for people. There are no animals, and there (5) ______ any trees."],"questions":[{"prompt":"1. Many children want to travel to the moon, but they ______ do it easily.","options":["A. can’t","B. aren’t","C. doesn’t"],"answer":0,"paragraph":0,"hint":"Busca la oración sobre viajar a la Luna. El sujeto es “they”.","why":"They can’t do it easily.","format":"multiple"},{"prompt":"2. The moon is not ______ good place for a holiday.","options":["A. a","B. an","C. the"],"answer":0,"paragraph":1,"hint":"“Good” empieza con sonido consonante.","why":"a good place","format":"multiple"},{"prompt":"3. It can be very cold ______ very hot.","options":["A. because","B. and","C. but"],"answer":1,"paragraph":1,"hint":"La oración une dos características que pueden ocurrir.","why":"and","format":"multiple"},{"prompt":"4. There isn’t ______ food for people.","options":["A. some","B. any","C. many"],"answer":1,"paragraph":1,"hint":"En una oración negativa con sustantivo incontable, usa la opción apropiada.","why":"any","format":"multiple"},{"prompt":"5. There ______ any trees.","options":["A. isn’t","B. aren’t","C. doesn’t"],"answer":1,"paragraph":1,"hint":"“Trees” es plural; completa There are not any trees.","why":"aren’t any trees.","format":"multiple"}]},{"type":"reading","eyebrow":"USE OF ENGLISH · A1","title":"Exercise B. Sport","time":"5 questions","paragraphs":["There are many different kinds (1) ______ sport. In football, players kick the ball, but in tennis, they hit it with a racket. Some people (2) ______ swimming because they enjoy the water.","Other people like running, cycling or playing basketball. Children often do sport at school because physical activity is (3) ______ for their health. Some sports are played alone, (4) ______ others need a team. Whatever sport you choose, it is important to have fun and (5) ______ active."],"questions":[{"prompt":"1. There are many different kinds ______ sport.","options":["A. of","B. at","C. on"],"answer":0,"paragraph":0,"hint":"La expresión fija es “kinds ___ sport”.","why":"of","format":"multiple"},{"prompt":"2. Some people ______ swimming.","options":["A. enjoys","B. enjoy","C. enjoying"],"answer":1,"paragraph":0,"hint":"El sujeto “some people” es plural.","why":"enjoy","format":"multiple"},{"prompt":"3. Physical activity is ______ for their health.","options":["A. good","B. best","C. better"],"answer":0,"paragraph":1,"hint":"La frase expresa un beneficio general, sin comparación.","why":"good","format":"multiple"},{"prompt":"4. Some sports are played alone, ______ others need a team.","options":["A. because","B. but","C. so"],"answer":1,"paragraph":1,"hint":"La segunda parte contrasta con la primera.","why":"but","format":"multiple"},{"prompt":"5. It is important to have fun and ______ active.","options":["A. stay","B. stays","C. stayed"],"answer":0,"paragraph":1,"hint":"Después de “and” continúa la forma base paralela a “have”.","why":"stay","format":"multiple"}]},{"type":"reading","eyebrow":"USE OF ENGLISH · A1","title":"Exercise C. Choosing a pet","time":"5 questions","paragraphs":["Choosing a pet is an important decision. You (1) ______ to think carefully before choosing an animal.","Dogs need exercise and like going (2) ______ walks with their owners. Cats are more independent, but they also need food, water and attention. Some families choose small animals, (3) ______ rabbits or hamsters.","Before you get a pet, think (4) ______ the space it needs and the food it eats. You must also decide (5) ______ can take care of it every day."],"questions":[{"prompt":"1. You ______ to think carefully.","options":["A. have","B. has","C. having"],"answer":0,"paragraph":0,"hint":"Con “you” se usa have.","why":"have","format":"multiple"},{"prompt":"2. Dogs like going ______ walks.","options":["A. for","B. at","C. in"],"answer":0,"paragraph":1,"hint":"La expresión es “go for walks”.","why":"for","format":"multiple"},{"prompt":"3. Some families choose small animals, ______ rabbits or hamsters.","options":["A. such","B. like","C. than"],"answer":1,"paragraph":1,"hint":"Aquí se dan ejemplos de animales pequeños.","why":"like","format":"multiple"},{"prompt":"4. Think ______ the space it needs.","options":["A. about","B. after","C. above"],"answer":0,"paragraph":2,"hint":"La expresión significa considerar algo: “think ___”.","why":"about","format":"multiple"},{"prompt":"5. Decide ______ can take care of it every day.","options":["A. who","B. where","C. when"],"answer":0,"paragraph":2,"hint":"La pregunta es por la persona responsable.","why":"who","format":"multiple"}]},{"type":"teacher","eyebrow":"ANSWER KEY · DOCENTE","title":"Respuestas · lecturas 1–7 y Use of English","items":[{"icon":"•","title":"Reading 1 · My School Festival","detail":"1. He is twelve years old. · 2. In October. · 3. Sandwiches, juice and cakes. · 4. The guitar. · 5. At three o’clock in the afternoon."},{"icon":"•","title":"Reading 2 · Pancake Day","detail":"1. True. · 2. False: February or March. · 3. True. · 4. True. · 5. False: children and adults celebrate it."},{"icon":"•","title":"Reading 3 · A weekend in London","detail":"1. B · 2. C · 3. A · 4. B · 5. D"},{"icon":"•","title":"Reading 4 · Healthy lifestyle","detail":"1. C · 2. A · 3. D · 4. B · 5. E"},{"icon":"•","title":"Reading 5 · Where are you going to shop?","detail":"1. A · 2. C · 3. B · 4. C · 5. A"},{"icon":"•","title":"Reading 6 · Empty houses","detail":"1. Some are old and need repairs; others are too expensive. · 2. Repair old houses and make them safe. · 3. Roofs, windows, doors, and water and electricity systems. · 4. Many families. · 5. B"},{"icon":"•","title":"Reading 7 · A helpful app","detail":"1. B · 2. A · 3. C · 4. B · 5. C"},{"icon":"•","title":"Use of English A · The moon","detail":"1. A — can’t · 2. A — a · 3. B — and · 4. B — any · 5. B — aren’t"},{"icon":"•","title":"Use of English B · Sport","detail":"1. A — of · 2. B — enjoy · 3. A — good · 4. B — but · 5. A — stay"},{"icon":"•","title":"Use of English C · Choosing a pet","detail":"1. A — have · 2. A — for · 3. B — like · 4. A — about · 5. A — who"}]},{"type":"teacher","eyebrow":"ANSWER KEY · DOCENTE","title":"Respuestas · lecturas 8–11","items":[{"icon":"•","title":"Reading 8 · My First Day at a New School","detail":"1. C · 2. A · 3. B · 4. D · 5. C"},{"icon":"•","title":"Reading 9 · A Day at the National Park","detail":"1. B · 2. A · 3. C · 4. D · 5. B"},{"icon":"•","title":"Reading 10 · The School Sports Competition","detail":"1. C · 2. B · 3. D · 4. A · 5. C · 6. B"},{"icon":"•","title":"Reading 11 · A New Café in Town","detail":"1. B · 2. D · 3. A · 4. C · 5. C · 6. B"}]}] as Slide[]));salomeQuiz.splice(0,salomeQuiz.length);
